(4995891, 728694, 94265, '<td valign="top">Good lighting and composition.</td>', 'Good lighting and composition.', '2008-10-06 21:52:07.000000', NULL, 1),
(4995895, 728739, 94265, '<td valign="top">Aww very pretty girls, nice shot.</td>', 'Aww very pretty girls, nice shot.', '2008-10-06 21:53:55.000000', NULL, 1),
