(4995909, 728734, 94265, '<td valign="top">If you''d used a little doll instead, this''d actually be a really cute, funny shot. Or even if you''d just had the wolf in the old lady hat.</td>', 'If you''d used a little doll instead, this''d actually be a really cute, funny shot. Or even if you''d just had the wolf in the old lady hat.', '2008-10-06 22:03:46.000000', NULL, 1),
(4995910, 728283, 94265, '<td valign="top">Brilliant! At first I didn''t understand why he was almost totally in shadow but then I read the story. This is a great interpretation of the story and such a beautiful portrait of a lion, so sharp. Well done!</td>', 'Brilliant! At first I didn''t understand why he was almost totally in shadow but then I read the story. This is a great interpretation of the story and such a beautiful portrait of a lion, so sharp. Well done!', '2008-10-06 22:03:49.000000', NULL, 1),
(4995918, 728193, 94265, '<td valign="top">Good composition, I like how just the one little area is lit, I''m guessing there''s a fire or torch or something directly in front of her? Nicely done.</td>', 'Good composition, I like how just the one little area is lit, I''m guessing there''s a fire or torch or something directly in front of her? Nicely done.', '2008-10-06 22:07:55.000000', NULL, 1),
(4995925, 728134, 94265, '<td valign="top">I like the composition and the amount of his face showing, you''ve got a bit of a halo going on though, maybe used a bit too much unsharp mask? His face seems a bit grainy.</td>', 'I like the composition and the amount of his face showing, you''ve got a bit of a halo going on though, maybe used a bit too much unsharp mask? His face seems a bit grainy.', '2008-10-06 22:12:12.000000', NULL, 1),
(4995933, 728024, 94265, '<td valign="top">This is cute and the warm light is nice, would''ve liked to have seen a little more light on the subjects.</td>', 'This is cute and the warm light is nice, would''ve liked to have seen a little more light on the subjects.', '2008-10-06 22:15:20.000000', NULL, 1),
(4995936, 728273, 94265, '<td valign="top">She''s very pretty, especially her green eyes but the pic has been softened too much, you''ve lost a fair bit of detail.</td>', 'She''s very pretty, especially her green eyes but the pic has been softened too much, you''ve lost a fair bit of detail.', '2008-10-06 22:17:14.000000', NULL, 1),
(4995937, 728738, 94265, '<td valign="top">I love the composition and the dark background, it looks great, just a bit too grainy.</td>', 'I love the composition and the dark background, it looks great, just a bit too grainy.', '2008-10-06 22:18:23.000000', NULL, 1),
(4995941, 728688, 94265, '<td valign="top">The perspective on this is really good, not sure why you''ve added that black bar at the top though?</td>', 'The perspective on this is really good, not sure why you''ve added that black bar at the top though?', '2008-10-06 22:19:23.000000', NULL, 1),
