(4996248, 727993, 69668, '<td valign="top">LOVE the mood created here.  Great post processing and the attire is terrific.</td>', 'LOVE the mood created here.  Great post processing and the attire is terrific.', '2008-10-07 01:09:02.000000', NULL, 1),
