(4997927, 728080, 57775, '<td valign="top">LOL</td>', 'LOL', '2008-10-08 00:48:48.000000', NULL, 1),
(4997933, 728684, 57775, '<td valign="top">I like the angle of your shot a lot and you have good lighting and a perfect model, but the grass is distracting and doesn''t add much to your photo.  I think it would have been much better to have her lying on a prettier bed of moss or flowers.</td>', 'I like the angle of your shot a lot and you have good lighting and a perfect model, but the grass is distracting and doesn''t add much to your photo.  I think it would have been much better to have her lying on a prettier bed of moss or flowers.', '2008-10-08 00:50:39.000000', NULL, 1),
