(5004699, 728709, 90414, '<td valign="top">I didn''t realize Faithful John was a football story... silly me! OK, I don''t get the connection (I assume there is one) but not a bad shot despite that.</td>', 'I didn''t realize Faithful John was a football story... silly me! OK, I don''t get the connection (I assume there is one) but not a bad shot despite that.', '2008-10-12 02:28:29.000000', NULL, 1),
(5004700, 728597, 90414, '<td valign="top">Cute shot with a comical title. Well done.</td>', 'Cute shot with a comical title. Well done.', '2008-10-12 02:30:01.000000', NULL, 1),
(5004701, 728699, 90414, '<td valign="top">A bit dark (a night shot I take?) but I like the color and textures on the goose. A little dodging of the background to bring out more detail might make a bit stronger and bolder shot.</td>', 'A bit dark (a night shot I take?) but I like the color and textures on the goose. A little dodging of the background to bring out more detail might make a bit stronger and bolder shot.', '2008-10-12 02:34:08.000000', NULL, 1),
(5004703, 728516, 90414, '<td valign="top">This is a very grand staircase, but just lacks mood for me.</td>', 'This is a very grand staircase, but just lacks mood for me.', '2008-10-12 02:36:13.000000', NULL, 1),
(5004756, 728562, 94265, '<td valign="top">I like the dull light in the woods, it makes the cape stand out more, the green/yellow could''ve easily dominated the shot.</td>', 'I like the dull light in the woods, it makes the cape stand out more, the green/yellow could''ve easily dominated the shot.', '2008-10-12 04:25:09.000000', NULL, 1),
(5004758, 728073, 94265, '<td valign="top">Nice shot and crop, I''d have upped the red hue just a little, her shawl looks more brown to me.</td>', 'Nice shot and crop, I''d have upped the red hue just a little, her shawl looks more brown to me.', '2008-10-12 04:25:59.000000', NULL, 1),
(5004759, 727771, 94265, '<td valign="top">Brilliant setting, the huge tree roots really make it fairytale-ish for me.</td>', 'Brilliant setting, the huge tree roots really make it fairytale-ish for me.', '2008-10-12 04:29:13.000000', NULL, 1),
