(5004939, 728615, 58452, '<td valign="top">Love the composition and the dark on dark. My choice for the blue. Congrats.</td>', 'Love the composition and the dark on dark. My choice for the blue. Congrats.', '2008-10-12 11:34:46.000000', NULL, 1),
(5004941, 728704, 58452, '<td valign="top">Love the pose, composition, expression on the face, everything.  Cute model. My choice for the red, of course.  Congrats.</td>', 'Love the pose, composition, expression on the face, everything.  Cute model. My choice for the red, of course.  Congrats.', '2008-10-12 11:36:08.000000', NULL, 1),
(5004942, 727495, 58452, '<td valign="top">I lost my balance when this popped up on the screen. Very nice composition. I wish the model were better separated from the rock . But that''s just a nit pic.  My choice for the yellow.  Congrats.</td>', 'I lost my balance when this popped up on the screen. Very nice composition. I wish the model were better separated from the rock . But that''s just a nit pic.  My choice for the yellow.  Congrats.', '2008-10-12 11:38:30.000000', NULL, 1),
(5004943, 728209, 58452, '<td valign="top">Nice composition. I can see you trying to get the frog to wear the crown.  Looks a little Scalvertesque. :p Gotta top ten. Congrats.</td>', 'Nice composition. I can see you trying to get the frog to wear the crown.  Looks a little Scalvertesque. :p Gotta top ten. Congrats.', '2008-10-12 11:39:40.000000', NULL, 1),
