(5004948, 728513, 58452, '<td valign="top">I know an old codger "who" looks exactly like this owl. Nice portrait.</td>', 'I know an old codger "who" looks exactly like this owl. Nice portrait.', '2008-10-12 11:41:31.000000', NULL, 1),
(5004951, 728024, 58452, '<td valign="top">Interesting setup.</td>', 'Interesting setup.', '2008-10-12 11:42:01.000000', NULL, 1),
(5005029, 728739, 90414, '<td valign="top">Very cute photo... you really captured those beautiful eyes! Well done.</td>', 'Very cute photo... you really captured those beautiful eyes! Well done.', '2008-10-12 14:10:08.000000', NULL, 1),
(5005031, 728734, 90414, '<td valign="top">Only <b>your </b>shoehorns are <i>literal</i> shoehorns!  Funny.</td>', 'Only your shoehorns are literal shoehorns!  Funny.', '2008-10-12 14:11:48.000000', NULL, 1),
(5005033, 728703, 90414, '<td valign="top">The desaturated parts really make the cape pop, but it looks either oversharpened or maybe it is the lighting making it glow. Very nice.</td>', 'The desaturated parts really make the cape pop, but it looks either oversharpened or maybe it is the lighting making it glow. Very nice.', '2008-10-12 14:13:49.000000', NULL, 1),
(5005035, 728710, 90414, '<td valign="top">Nicely set up shot - is that a real frog wearing a crown? Nicely done!</td>', 'Nicely set up shot - is that a real frog wearing a crown? Nicely done!', '2008-10-12 14:15:09.000000', NULL, 1),
(5005040, 728665, 90414, '<td valign="top">Nice architectural shot, but I don''t get the tie-in... unless she''s got <b>really </b>long hair.</td>', 'Nice architectural shot, but I don''t get the tie-in... unless she''s got really long hair.', '2008-10-12 14:17:57.000000', NULL, 1),
(5005041, 728623, 90414, '<td valign="top">LOL, well executed shot!</td>', 'LOL, well executed shot!', '2008-10-12 14:19:40.000000', NULL, 1),
(5005044, 728712, 90414, '<td valign="top">Nice composition, but not very vibrant to me. Maybe you desaturated to give it a vintage feel?</td>', 'Nice composition, but not very vibrant to me. Maybe you desaturated to give it a vintage feel?', '2008-10-12 14:24:04.000000', NULL, 1),
(5005046, 728581, 90414, '<td valign="top">Beautiful fall colors and color range. Excellent composition - well done!</td>', 'Beautiful fall colors and color range. Excellent composition - well done!', '2008-10-12 14:26:49.000000', NULL, 1),
(5005047, 728552, 90414, '<td valign="top">Nice capture - looks like very harsh environment.</td>', 'Nice capture - looks like very harsh environment.', '2008-10-12 14:29:16.000000', NULL, 1),
(5005048, 728515, 90414, '<td valign="top">Not a bad shot, but there are so many really great photos in this challenge, this one just pales by comparison imo... sorry.</td>', 'Not a bad shot, but there are so many really great photos in this challenge, this one just pales by comparison imo... sorry.', '2008-10-12 14:31:49.000000', NULL, 1),
(5005193, 728193, 64518, '<td valign="top">Love it!</td>', 'Love it!', '2008-10-12 16:47:24.000000', NULL, 1),
(5005214, 728516, 30490, '<td valign="top">Beautiful stairway, nicely lit, it just needs a glass slipper to really be on target for this challenge.</td>', 'Beautiful stairway, nicely lit, it just needs a glass slipper to really be on target for this challenge.', '2008-10-12 17:07:38.000000', NULL, 1),
(5005218, 728693, 30490, '<td valign="top">Love the idea and the image.  I think the bird is in focus, but the flower in the background is so large and out of focus that it draws the eye away from the beautiful bird and because the color tones are so similar make the bird appear to be out of focus as well.  I guess to sum it up in a short but simple way the foreground and backgroung are at war for focus in this image, and it ends up hurting the eyes.</td>', 'Love the idea and the image.  I think the bird is in focus, but the flower in the background is so large and out of focus that it draws the eye away from the beautiful bird and because the color tones are so similar make the bird appear to be out of focus as well.  I guess to sum it up in a short but simple way the foreground and backgroung are at war for focus in this image, and it ends up hurting the eyes.', '2008-10-12 17:10:43.000000', NULL, 1),
(5005220, 728682, 30490, '<td valign="top">Two really cute kids!</td>', 'Two really cute kids!', '2008-10-12 17:11:19.000000', NULL, 1),
(5005222, 728739, 30490, '<td valign="top">Aren''t they little darlings!  What a beautiful portrait!  The eyes are just magnificent!</td>', 'Aren''t they little darlings!  What a beautiful portrait!  The eyes are just magnificent!', '2008-10-12 17:12:27.000000', NULL, 1),
(5005225, 727840, 30490, '<td valign="top">hmmm interesting.... looks like an abstract watercolor.  very interesting photo technique.</td>', 'hmmm interesting.... looks like an abstract watercolor.  very interesting photo technique.', '2008-10-12 17:13:21.000000', NULL, 1),
(5005226, 728710, 30490, '<td valign="top">Love It!  The frog looks like he has had enough already!</td>', 'Love It!  The frog looks like he has had enough already!', '2008-10-12 17:14:00.000000', NULL, 1),
(5005227, 728674, 30490, '<td valign="top">Love the play on words in the image and the title</td>', 'Love the play on words in the image and the title', '2008-10-12 17:14:19.000000', NULL, 1),
(5005228, 728684, 30490, '<td valign="top">I kind of wish the apple wasn''t so far in the foreground. But overall a good image.</td>', 'I kind of wish the apple wasn''t so far in the foreground. But overall a good image.', '2008-10-12 17:14:56.000000', NULL, 1),
(5005232, 726370, 30490, '<td valign="top">Great job with tough models.  How did you bribe them to do what you asked?  By the way what kind of turtle/tortoise is this?</td>', 'Great job with tough models.  How did you bribe them to do what you asked?  By the way what kind of turtle/tortoise is this?', '2008-10-12 17:16:10.000000', NULL, 1),
