(5005323, 727815, 90414, '<td valign="top">Lovely shot, but that branch that parallels her spine really bugs me the more I look at the photo. Still a strong shot.</td>', 'Lovely shot, but that branch that parallels her spine really bugs me the more I look at the photo. Still a strong shot.', '2008-10-12 19:29:03.000000', NULL, 1),
(5005326, 728123, 90414, '<td valign="top">This is an amazing photo: beautiful lighting (light painting/night shot I am sure). Hope you include how you did this! Top 5 I would suspect.</td>', 'This is an amazing photo: beautiful lighting (light painting/night shot I am sure). Hope you include how you did this! Top 5 I would suspect.', '2008-10-12 19:33:17.000000', NULL, 1),
(5005327, 727703, 90414, '<td valign="top">Nice shot, but perhaps too much dead space near the woodpile. Still, well executed.</td>', 'Nice shot, but perhaps too much dead space near the woodpile. Still, well executed.', '2008-10-12 19:35:11.000000', NULL, 1),
(5005334, 728613, 90414, '<td valign="top">Intriguing abstract shot in a challenge with very strong contenders.</td>', 'Intriguing abstract shot in a challenge with very strong contenders.', '2008-10-12 19:40:39.000000', NULL, 1),
(5005339, 727975, 90414, '<td valign="top">Beautiful shot, perhaps could have cropped a bit more off the right, but well done.</td>', 'Beautiful shot, perhaps could have cropped a bit more off the right, but well done.', '2008-10-12 19:45:49.000000', NULL, 1),
(5005345, 728560, 90414, '<td valign="top">Beautiful, well planned shot for Rapunzel.</td>', 'Beautiful, well planned shot for Rapunzel.', '2008-10-12 19:47:35.000000', NULL, 1),
(5005347, 728490, 65234, '<td valign="top">Oh, man, I just went and read that story and it''s heartbreaking :-(  The lack of eye makeup works well here to suggest someone who''s cried it all off, and now the eyes are dry, but still sad.  Don''t know about the flowers but overall an emotive image which suits the story.</td>', 'Oh, man, I just went and read that story and it''s heartbreaking :-(  The lack of eye makeup works well here to suggest someone who''s cried it all off, and now the eyes are dry, but still sad.  Don''t know about the flowers but overall an emotive image which suits the story.', '2008-10-12 19:49:25.000000', NULL, 1),
(5005348, 728134, 90414, '<td valign="top">It fits the challenge, and in truth isn''t a bad photo, imo. This challenge has some really strong shots, though, which will just score better.</td>', 'It fits the challenge, and in truth isn''t a bad photo, imo. This challenge has some really strong shots, though, which will just score better.', '2008-10-12 19:49:50.000000', NULL, 1),
(5005350, 728193, 65234, '<td valign="top">Like the lighting and the candle in the midst of the dark and scary woods.</td>', 'Like the lighting and the candle in the midst of the dark and scary woods.', '2008-10-12 19:49:55.000000', NULL, 1),
(5005352, 728734, 65234, '<td valign="top">Umm, er, well .. yes, it''s a shoehorn in a red capeish object with a wolfie sort of action figure.  More creative than anything I came up with (which was nothing at all!).</td>', 'Umm, er, well .. yes, it''s a shoehorn in a red capeish object with a wolfie sort of action figure.  More creative than anything I came up with (which was nothing at all!).', '2008-10-12 19:51:35.000000', NULL, 1),
(5005354, 728682, 65234, '<td valign="top">Nicely dreamy, but I hope they both sleep till they grow up a lot more!!</td>', 'Nicely dreamy, but I hope they both sleep till they grow up a lot more!!', '2008-10-12 19:52:12.000000', NULL, 1),
(5005355, 728703, 65234, '<td valign="top">Selective desat is a good idea.  She looks rather flirty, or maybe about to break out in a grin.  Certainly quite the self-confident fairy tale heroine.</td>', 'Selective desat is a good idea.  She looks rather flirty, or maybe about to break out in a grin.  Certainly quite the self-confident fairy tale heroine.', '2008-10-12 19:53:20.000000', NULL, 1),
(5005356, 728024, 65234, '<td valign="top">Those elves look suspiciously troll-like ;-)  Nice lighting.</td>', 'Those elves look suspiciously troll-like ;-)  Nice lighting.', '2008-10-12 19:53:50.000000', NULL, 1),
(5005358, 728627, 90414, '<td valign="top">A strong and unique photo in this challenge, well done. <br/>Isn''t the name of the story supposed to be the title?</td>', 'A strong and unique photo in this challenge, well done. Isn''t the name of the story supposed to be the title?', '2008-10-12 19:53:52.000000', NULL, 1),
(5005360, 728193, 90414, '<td valign="top">Wonderful shot!</td>', 'Wonderful shot!', '2008-10-12 19:54:51.000000', NULL, 1),
(5005361, 728615, 67152, '<td valign="top">Awesome image - my favorite in the challenge</td>', 'Awesome image - my favorite in the challenge', '2008-10-12 19:55:43.000000', NULL, 1),
(5005362, 727993, 67152, '<td valign="top">outstanding feel to this creepy image - good work</td>', 'outstanding feel to this creepy image - good work', '2008-10-12 19:56:01.000000', NULL, 1),
(5005363, 727645, 67152, '<td valign="top">the painted feel of the background is outstanding to add to the storybook feel of the image</td>', 'the painted feel of the background is outstanding to add to the storybook feel of the image', '2008-10-12 19:56:19.000000', NULL, 1),
(5005364, 728170, 67152, '<td valign="top">graphic and light as if a drawing in a real storybook</td>', 'graphic and light as if a drawing in a real storybook', '2008-10-12 19:56:44.000000', NULL, 1),
(5005365, 728490, 67152, '<td valign="top">the textures, the stare, the tones - very dramatic stuff</td>', 'the textures, the stare, the tones - very dramatic stuff', '2008-10-12 19:57:05.000000', NULL, 1),
(5005366, 727703, 67152, '<td valign="top">beautiful lighting to emphasize Cinderella - the bare feet is a great touch</td>', 'beautiful lighting to emphasize Cinderella - the bare feet is a great touch', '2008-10-12 19:57:36.000000', NULL, 1),
(5005368, 727735, 67152, '<td valign="top">the vibrant colors work very well here - the path leading on and the happy look to her step counters the events about to take place....</td>', 'the vibrant colors work very well here - the path leading on and the happy look to her step counters the events about to take place....', '2008-10-12 19:58:12.000000', NULL, 1),
(5005369, 728277, 90414, '<td valign="top">There are many Little Red Cap photos in this challenge, but this is the one that feels the most dangerous, dark, and menacing for her. Love the tree line.</td>', 'There are many Little Red Cap photos in this challenge, but this is the one that feels the most dangerous, dark, and menacing for her. Love the tree line.', '2008-10-12 19:58:21.000000', NULL, 1),
(5005370, 728193, 67152, '<td valign="top">the look opposite the candle adds to the tension - i am just not convinced about the centered composition... still it got a 7</td>', 'the look opposite the candle adds to the tension - i am just not convinced about the centered composition... still it got a 7', '2008-10-12 19:58:53.000000', NULL, 1),
(5005371, 728684, 67152, '<td valign="top">lovely focus on her face - good costume and great colors</td>', 'lovely focus on her face - good costume and great colors', '2008-10-12 19:59:13.000000', NULL, 1),
(5005372, 728712, 67152, '<td valign="top">the horror in her face - the dropped rocks/ bread crumbs - good work</td>', 'the horror in her face - the dropped rocks/ bread crumbs - good work', '2008-10-12 19:59:39.000000', NULL, 1),
(5005373, 728710, 67152, '<td valign="top">luscious tones and textures all around - stupid frog...very stupid frog...</td>', 'luscious tones and textures all around - stupid frog...very stupid frog...', '2008-10-12 20:00:00.000000', NULL, 1),
(5005374, 728025, 67152, '<td valign="top">awesome lighting on the face - i just really am not a fan here of the completely desaturated background - the subtle saturation in the basket was outstanding - continuing this treatment in the woods behind would added a couple of points (still it gets a 7)</td>', 'awesome lighting on the face - i just really am not a fan here of the completely desaturated background - the subtle saturation in the basket was outstanding - continuing this treatment in the woods behind would added a couple of points (still it gets a 7)', '2008-10-12 20:01:14.000000', NULL, 1),
(5005375, 728709, 65234, '<td valign="top">Well, THAT was one heck of a tale to read!  I''m learning a lot voting on this challenge :-)  Not sure he was a football player, but a statue certainly suits the story.  I might have cropped closer, maybe a study of his face?</td>', 'Well, THAT was one heck of a tale to read!  I''m learning a lot voting on this challenge :-)  Not sure he was a football player, but a statue certainly suits the story.  I might have cropped closer, maybe a study of his face?', '2008-10-12 20:01:16.000000', NULL, 1),
(5005376, 728513, 67152, '<td valign="top">awesome focus on the owl - i had to go look to find the story - never heard of it before</td>', 'awesome focus on the owl - i had to go look to find the story - never heard of it before', '2008-10-12 20:01:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5005377, 728057, 65234, '<td valign="top">Cool; you found a glass slipper!  Looks almost well-worn.</td>', 'Cool; you found a glass slipper!  Looks almost well-worn.', '2008-10-12 20:01:51.000000', NULL, 1),
(5005378, 728440, 67152, '<td valign="top">the eery feeling of this secluded path really tells the story - i don''t need the red hood to feel the setting</td>', 'the eery feeling of this secluded path really tells the story - i don''t need the red hood to feel the setting', '2008-10-12 20:02:12.000000', NULL, 1),
(5005380, 728540, 67152, '<td valign="top">nice approach - the apple is perfect - nice and bright - the skin so pale as if sleep has taken hold immediately...</td>', 'nice approach - the apple is perfect - nice and bright - the skin so pale as if sleep has taken hold immediately...', '2008-10-12 20:02:44.000000', NULL, 1),
(5005382, 728694, 67152, '<td valign="top">those are some creepy hands with those nails - i am not coming to your house for Halloween...</td>', 'those are some creepy hands with those nails - i am not coming to your house for Halloween...', '2008-10-12 20:03:09.000000', NULL, 1),
(5005384, 728704, 67152, '<td valign="top">pretty girl - nice full frame approach - a bit too much work on the eyes for my taste - especially the whites</td>', 'pretty girl - nice full frame approach - a bit too much work on the eyes for my taste - especially the whites', '2008-10-12 20:03:38.000000', NULL, 1),
(5005386, 728581, 67152, '<td valign="top">excellent feel - lovely painting life feel - back for a comment and a bump</td>', 'excellent feel - lovely painting life feel - back for a comment and a bump', '2008-10-12 20:03:56.000000', NULL, 1),
